-- ============================================================================
-- Warehouse Intelligence Platform — Supabase PostgreSQL Schema & Seed Script
-- Run this entire script in your Supabase SQL Editor (Dashboard -> SQL Editor)
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Cleanly drop any previous tables
DROP TABLE IF EXISTS detections CASCADE;
DROP TABLE IF EXISTS object_tracks CASCADE;
DROP TABLE IF EXISTS frame_records CASCADE;
DROP TABLE IF EXISTS behaviour_observations CASCADE;
DROP TABLE IF EXISTS telemetry_points CASCADE;
DROP TABLE IF EXISTS video_processing_jobs CASCADE;
DROP TABLE IF EXISTS incident_reviews CASCADE;
DROP TABLE IF EXISTS risk_assessments CASCADE;
DROP TABLE IF EXISTS events CASCADE;
DROP TABLE IF EXISTS inference_runs CASCADE;
DROP TABLE IF EXISTS videos CASCADE;
DROP TABLE IF EXISTS safety_rules CASCADE;
DROP TABLE IF EXISTS cameras CASCADE;
DROP TABLE IF EXISTS shifts CASCADE;
DROP TABLE IF EXISTS loading_bays CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS facilities CASCADE;
DROP TABLE IF EXISTS organizations CASCADE;
DROP TABLE IF EXISTS model_runs CASCADE;
DROP TABLE IF EXISTS audit_logs CASCADE;
DROP TABLE IF EXISTS evaluation_samples CASCADE;
DROP TABLE IF EXISTS evaluation_datasets CASCADE;

-- 2. Create Table Definitions
CREATE TABLE organizations (
    id VARCHAR PRIMARY KEY NOT NULL,
    name VARCHAR NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE facilities (
    id VARCHAR PRIMARY KEY NOT NULL,
    organization_id VARCHAR,
    name VARCHAR NOT NULL,
    location VARCHAR,
    timezone VARCHAR,
    status VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE users (
    id VARCHAR PRIMARY KEY NOT NULL,
    organization_id VARCHAR,
    email VARCHAR NOT NULL,
    hashed_password VARCHAR NOT NULL,
    full_name VARCHAR NOT NULL,
    role VARCHAR NOT NULL,
    facility_id VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE loading_bays (
    id VARCHAR PRIMARY KEY NOT NULL,
    facility_id VARCHAR NOT NULL,
    name VARCHAR NOT NULL,
    code VARCHAR NOT NULL,
    status VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE shifts (
    id VARCHAR PRIMARY KEY NOT NULL,
    facility_id VARCHAR NOT NULL,
    name VARCHAR NOT NULL,
    start_time VARCHAR NOT NULL,
    end_time VARCHAR NOT NULL,
    timezone VARCHAR,
    active BOOLEAN
);

CREATE TABLE cameras (
    id VARCHAR PRIMARY KEY NOT NULL,
    loading_bay_id VARCHAR,
    name VARCHAR NOT NULL,
    camera_code VARCHAR NOT NULL,
    source_type VARCHAR,
    stream_url VARCHAR,
    status VARCHAR,
    last_seen_at TIMESTAMP WITHOUT TIME ZONE,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE safety_rules (
    id VARCHAR PRIMARY KEY NOT NULL,
    facility_id VARCHAR NOT NULL,
    name VARCHAR NOT NULL,
    description TEXT,
    behaviour_type VARCHAR NOT NULL,
    threshold_config_json TEXT,
    risk_level VARCHAR NOT NULL,
    enabled BOOLEAN,
    created_at TIMESTAMP WITHOUT TIME ZONE,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE videos (
    video_id VARCHAR PRIMARY KEY NOT NULL,
    camera_id VARCHAR,
    uploaded_by_user_id VARCHAR,
    filename VARCHAR,
    storage_key VARCHAR,
    mime_type VARCHAR,
    frame_count INTEGER,
    fps FLOAT,
    width INTEGER,
    height INTEGER,
    duration FLOAT,
    status VARCHAR,
    processed_at TIMESTAMP WITHOUT TIME ZONE,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE inference_runs (
    id VARCHAR PRIMARY KEY NOT NULL,
    video_id VARCHAR,
    camera_id VARCHAR,
    model_name VARCHAR NOT NULL,
    model_version VARCHAR NOT NULL,
    model_path VARCHAR,
    model_sha256 VARCHAR,
    inference_engine VARCHAR NOT NULL,
    device VARCHAR,
    status VARCHAR,
    started_at TIMESTAMP WITHOUT TIME ZONE,
    completed_at TIMESTAMP WITHOUT TIME ZONE,
    error_message TEXT,
    provenance_type VARCHAR
);

CREATE TABLE behaviour_observations (
    id VARCHAR PRIMARY KEY NOT NULL,
    inference_run_id VARCHAR NOT NULL,
    video_id VARCHAR NOT NULL,
    track_id INTEGER,
    frame_number INTEGER NOT NULL,
    timestamp FLOAT NOT NULL,
    behaviour_type VARCHAR NOT NULL,
    confidence FLOAT NOT NULL,
    details_json TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE events (
    event_id VARCHAR PRIMARY KEY NOT NULL,
    organization_id VARCHAR,
    facility_id VARCHAR,
    video_id VARCHAR,
    timestamp FLOAT,
    camera_id VARCHAR,
    bay_id VARCHAR,
    object_id INTEGER,
    behaviour VARCHAR,
    risk_score FLOAT,
    risk_level VARCHAR,
    description TEXT,
    reason TEXT,
    potential_consequence TEXT,
    risk_factors_json TEXT,
    evidence_frame VARCHAR,
    video_reference VARCHAR,
    recommended_action TEXT,
    status VARCHAR,
    acknowledged_by_user_id VARCHAR,
    acknowledged_at TIMESTAMP WITHOUT TIME ZONE,
    model_name VARCHAR,
    model_version VARCHAR,
    inference_engine VARCHAR,
    confidence FLOAT,
    provenance_type VARCHAR,
    environment VARCHAR,
    is_test_data BOOLEAN,
    is_demo_data BOOLEAN,
    inference_run_id VARCHAR,
    risk_assessment_id VARCHAR,
    behaviour_observation_id VARCHAR,
    frame_number INTEGER,
    video_fps FLOAT,
    timestamp_seconds FLOAT,
    timestamp_utc TIMESTAMP WITHOUT TIME ZONE,
    evidence_clip_start FLOAT,
    evidence_clip_end FLOAT,
    processing_latency_ms FLOAT,
    rule_version VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE risk_assessments (
    id VARCHAR PRIMARY KEY NOT NULL,
    event_id VARCHAR NOT NULL,
    behaviour_observation_id VARCHAR,
    risk_level VARCHAR NOT NULL,
    risk_score FLOAT NOT NULL,
    confidence FLOAT NOT NULL,
    reason TEXT,
    risk_factors_json TEXT,
    potential_consequence TEXT,
    model_version VARCHAR,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE incident_reviews (
    id VARCHAR PRIMARY KEY NOT NULL,
    event_id VARCHAR NOT NULL,
    reviewer_id VARCHAR NOT NULL,
    decision VARCHAR NOT NULL,
    comment TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE video_processing_jobs (
    id VARCHAR PRIMARY KEY NOT NULL,
    video_id VARCHAR NOT NULL,
    job_type VARCHAR,
    status VARCHAR,
    model_version VARCHAR,
    started_at TIMESTAMP WITHOUT TIME ZONE,
    completed_at TIMESTAMP WITHOUT TIME ZONE,
    error_message TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE telemetry_points (
    id SERIAL PRIMARY KEY,
    video_id VARCHAR,
    session_id VARCHAR,
    timestamp FLOAT,
    risk_score FLOAT,
    status VARCHAR,
    violations_json TEXT,
    boxes_json TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE frame_records (
    id VARCHAR PRIMARY KEY NOT NULL,
    inference_run_id VARCHAR NOT NULL,
    video_id VARCHAR NOT NULL,
    frame_number INTEGER NOT NULL,
    timestamp_ms FLOAT NOT NULL,
    width INTEGER,
    height INTEGER,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE object_tracks (
    id SERIAL PRIMARY KEY,
    inference_run_id VARCHAR,
    video_id VARCHAR NOT NULL,
    track_id INTEGER NOT NULL,
    object_type VARCHAR NOT NULL,
    start_timestamp_ms FLOAT NOT NULL,
    end_timestamp_ms FLOAT NOT NULL,
    confidence FLOAT NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE detections (
    id SERIAL PRIMARY KEY,
    inference_run_id VARCHAR,
    frame_id VARCHAR,
    video_id VARCHAR NOT NULL,
    camera_id VARCHAR,
    timestamp_ms FLOAT NOT NULL,
    frame_number INTEGER,
    object_type VARCHAR NOT NULL,
    track_id INTEGER,
    confidence FLOAT NOT NULL,
    bbox_x FLOAT NOT NULL,
    bbox_y FLOAT NOT NULL,
    bbox_width FLOAT NOT NULL,
    bbox_height FLOAT NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE model_runs (
    id VARCHAR PRIMARY KEY NOT NULL,
    model_name VARCHAR NOT NULL,
    model_version VARCHAR NOT NULL,
    device VARCHAR,
    fps FLOAT,
    latency_ms FLOAT,
    confidence_threshold FLOAT,
    started_at TIMESTAMP WITHOUT TIME ZONE,
    status VARCHAR
);

CREATE TABLE audit_logs (
    id VARCHAR PRIMARY KEY NOT NULL,
    organization_id VARCHAR,
    user_id VARCHAR,
    action VARCHAR NOT NULL,
    entity_type VARCHAR NOT NULL,
    entity_id VARCHAR NOT NULL,
    metadata_json TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE evaluation_datasets (
    id VARCHAR PRIMARY KEY NOT NULL,
    name VARCHAR NOT NULL,
    version VARCHAR NOT NULL,
    behaviour_class VARCHAR,
    sample_count INTEGER,
    description TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE evaluation_samples (
    id VARCHAR PRIMARY KEY NOT NULL,
    dataset_id VARCHAR NOT NULL,
    video_id VARCHAR,
    frame_number INTEGER,
    timestamp FLOAT,
    ground_truth_label VARCHAR NOT NULL,
    predicted_label VARCHAR NOT NULL,
    confidence FLOAT NOT NULL,
    is_correct BOOLEAN NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE
);

